/bin/zsh -lc "python3 -B - <<'PY'
from pathlib import Path
import difflib
for original in ('.pre-repair', '.baseline'):
    for name in ('vault.py', 'app.py', 'test_regression.py'):
        previous = Path(original) / name
        current = Path(name)
        if previous.exists():
            print(''.join(difflib.unified_diff(previous.read_text().splitlines(True), current.read_text().splitlines(True), fromfile=str(previous), tofile=name)))
        elif original == '.baseline':
            print(f'{name}: added since original baseline')
